1	package api
2	
3	import (
4		"encoding/json"
5		"errors"
6		"io"
7		"net/http"
8		"strings"
9	
10		"github.com/gin-gonic/gin"
11	
12		"github.com/Bob-xisuke/orb-netpolicy-guard/internal/store"
13	)
14	
15	// Error codes published by the service contract in README.md.
16	const (
17		codeInvalidInput = "InvalidNetPolicyInputError"
18		codeConflict     = "NetPolicyConflictError"
19		codeNotFound     = "NetPolicyNotFoundError"
20		codeStorage      = "storage_unavailable"
21	)
22	
23	// NewRouter wires the public HTTP surface. The service contract in README.md
24	// describes the error shape every entry must keep.
25	func NewRouter(st *store.Store) *gin.Engine {
26		gin.SetMode(gin.ReleaseMode)
27		router := gin.New()
28		router.Use(gin.Recovery())
29	
30		router.GET("/healthz", func(c *gin.Context) {
31			if err := st.Ping(); err != nil {
32				writeError(c, http.StatusServiceUnavailable, codeStorage, "database is not available")
33				return
34			}
35			c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
36		})
37	
38		router.POST("/v1/net-policies", func(c *gin.Context) {
39			rec, ok := decodeNetPolicy(c.Request.Body)
40			if !ok {
41				writeError(c, http.StatusBadRequest, codeInvalidInput, "request body is not a valid net policy")
42				return
43			}
44			stored, created, err := st.Register(rec)
45			if errors.Is(err, store.ErrConflict) {
46				writeError(c, http.StatusConflict, codeConflict, "a different net policy already exists for this namespace and name")
47				return
48			}
49			if err != nil {
50				writeError(c, http.StatusServiceUnavailable, codeStorage, "database is not available")
51				return
52			}
53			status := http.StatusOK
54			if created {
55				status = http.StatusCreated
56			}
57			c.JSON(status, stored)
58		})
59	
60		router.GET("/v1/net-policies", func(c *gin.Context) {
61			query := c.Request.URL.Query()
62			namespace, ok := singleQueryValue(query, "namespace")
63			if !ok {
64				writeError(c, http.StatusBadRequest, codeInvalidInput, "namespace must appear at most once and be non-blank")
65				return
66			}
67			label, ok := singleQueryValue(query, "label")
68			if !ok {
69				writeError(c, http.StatusBadRequest, codeInvalidInput, "label must appear at most once and be non-blank")
70				return
71			}
72			if namespace == "" && label == "" {
73				writeError(c, http.StatusBadRequest, codeInvalidInput, "namespace or label is required")
74				return
75			}
76			records, err := st.List(namespace, label)
77			if err != nil {
78				writeError(c, http.StatusServiceUnavailable, codeStorage, "database is not available")
79				return
80			}
81			if len(records) == 0 {
82				writeError(c, http.StatusNotFound, codeNotFound, "no net policies match the query")
83				return
84			}
85			c.JSON(http.StatusOK, gin.H{"items": records})
86		})
87	
88		router.NoRoute(func(c *gin.Context) {
89			writeError(c, http.StatusNotFound, "route_not_found", "no route matches this path")
90		})
91		return router
92	}
93	
94	func writeError(c *gin.Context, status int, code, message string) {
95		c.JSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
96	}
97	
98	// singleQueryValue accepts a parameter that appears at most once with a non-blank
99	// value. Absent yields ("", true); duplicated or blank yields ("", false).
100	func singleQueryValue(query map[string][]string, key string) (string, bool) {
101		values, present := query[key]
102		if !present {
103			return "", true
104		}
105		if len(values) != 1 || strings.TrimSpace(values[0]) == "" {
106			return "", false
107		}
108		return values[0], true
109	}
110	
111	// decodeNetPolicy strictly validates the request body: a single JSON object with
112	// the required fields, enums, and port intervals from the service contract.
113	func decodeNetPolicy(body io.Reader) (store.Record, bool) {
114		var raw map[string]json.RawMessage
115		decoder := json.NewDecoder(body)
116		if err := decoder.Decode(&raw); err != nil {
117			return store.Record{}, false
118		}
119		var trailing any
120		if err := decoder.Decode(&trailing); err != io.EOF {
121			return store.Record{}, false
122		}
123	
124		var rec store.Record
125		var ok bool
126		if rec.Namespace, ok = requiredString(raw, "namespace"); !ok {
127			return store.Record{}, false
128		}
129		if rec.Name, ok = requiredString(raw, "name"); !ok {
130			return store.Record{}, false
131		}
132		if rec.Label, ok = requiredString(raw, "label"); !ok {
133			return store.Record{}, false
134		}
135		if rec.Rules, ok = decodeRules(raw); !ok {
136			return store.Record{}, false
137		}
138		if rec.PluginParams, ok = decodePluginParams(raw); !ok {
139			return store.Record{}, false
140		}
141		return rec, true
142	}
143	
144	// requiredString reads a present, non-blank JSON string field.
145	func requiredString(raw map[string]json.RawMessage, key string) (string, bool) {
146		blob, present := raw[key]
147		if !present {
148			return "", false
149		}
150		var value string
151		if err := json.Unmarshal(blob, &value); err != nil {
152			return "", false
153		}
